148	/**
149	 * Lists (or searches) knowledge insights stored in the ledger's `.knowledge/` directory.
150	 *
151	 * - When `query` is present, delegates to `KnowledgeStoreManager.searchInsights()`.
152	 * - Otherwise calls `KnowledgeStoreManager.listInsights()` with scope/category/tags filters.
153	 * - `scope` is validated via `InsightScope.safeParse()`; unrecognised values are silently
154	 *   treated as "no scope filter" rather than causing an error.
155	 * - `tags` is a comma-separated string that is split before being forwarded.
156	 * - `limit` and `offset` are coerced to non-negative integers; invalid/missing values
157	 *   are silently ignored (limit → undefined, offset → 0).
158	 * - `limit=0` is treated as unlimited (mapped to undefined); pass a positive integer
159	 *   to enforce a page size.
160	 */
161	export async function handleListKnowledge(
162	  ledgerRoot: string,
163	  params: KnowledgeListParams = {}
164	): Promise<Insight[]> {
165	  const manager = new KnowledgeStoreManager(ledgerRoot);
166	
167	  // Validate scope — unrecognised values fall back to undefined (no filter).
168	  const scopeResult = InsightScope.safeParse(params.scope);
169	  const scope = scopeResult.success ? scopeResult.data : undefined;
170	
171	  const category = params.category ?? undefined;
172	  const repository_name = params.repository_name ?? undefined;
173	
174	  // Split comma-separated tags; ignore empty segments.
175	  const tags =
176	    params.tags && params.tags.trim().length > 0
177	      ? params.tags
178	          .split(',')
179	          .map((t) => t.trim())
180	          .filter((t) => t.length > 0)
181	      : undefined;
182	
183	  // Coerce pagination params.
184	  const limitRaw = params.limit !== undefined ? Math.floor(Number(params.limit)) : NaN;
185	  const limit = !isNaN(limitRaw) && limitRaw > 0 ? limitRaw : undefined;
186	
187	  const offsetRaw = params.offset !== undefined ? Math.floor(Number(params.offset)) : NaN;
188	  const offset = !isNaN(offsetRaw) && offsetRaw >= 0 ? offsetRaw : 0;
189	
190	  if (params.query && params.query.trim().length > 0) {
191	    return manager.searchInsights(params.query.trim(), { scope, repository_name, category, tags, limit, offset });
192	  }
193	
194	  return manager.listInsights({ scope, category, tags, repository_name, limit, offset });
195	}
